//! Text every generated file shares: the notice on its first line, and string literals for each language.

use rastai_diag::diagnostic::Severity;
use serde_json::Value;

/// The first line of every generated file, after the language's comment marker. rastai-diag's CLAUDE.md and
/// check-generated's messages say the same: never edit, regenerate.
pub const GENERATED_NOTICE: &str = "Generated by rastai-codegen. Do not edit.";

/// The second line of every catalog output: where its contents come from and how to change them.
pub const CATALOG_SOURCE_NOTE: &str = "Source: catalog/ and plugins/*/catalog/ (layout rust-control-plane.md 2.6); change those, then run `just codegen`.";

/// The second line of every rastai-formats-codegen output: the type descriptions and the command table it reads.
pub const FORMATS_SOURCE_NOTE: &str = "Source: the type descriptions in crates/rastai-formats and the core command table (layout rust-control-plane.md 4.9); change those, then run `just codegen`.";

/// A Rust string literal that reads back as exactly `text`. Rust's own Debug formatting of a string writes one,
/// escaping quotes, backslashes and control characters.
pub fn rust_string_literal(text: &str) -> String {
    format!("{text:?}")
}

/// A JSON string literal for `text`. JavaScript (since ES2019) and Python read every JSON string literal as the same
/// string, so the JavaScript and Python outputs both use it: quotes, backslashes and control characters are escaped,
/// everything else stays as written.
pub fn json_string_literal(text: &str) -> String {
    Value::String(text.to_string()).to_string()
}

/// The word the catalog JSON uses for a severity. The JavaScript, Python and docs outputs keep it as written.
///
/// rastai-diag's `severity_name` gives the same words today, but it is crate-private and answers a different
/// question (the label a rendered diagnostic shows). This is the catalog file's spelling, which catalog_source.rs
/// reads back, so the codegen keeps its own three lines instead of widening rastai-diag's public API.
pub fn severity_word(severity: Severity) -> &'static str {
    match severity {
        Severity::Error => "error",
        Severity::Warning => "warning",
        Severity::Info => "info",
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const AWKWARD_TEXT: &str = "say \"hi\"\\ then\nnext line\ttab é ✓";

    #[test]
    fn rust_literal_escapes_quotes_backslashes_and_control_characters() {
        assert_eq!(
            rust_string_literal(AWKWARD_TEXT),
            r#""say \"hi\"\\ then\nnext line\ttab é ✓""#
        );
    }

    #[test]
    fn json_literal_escapes_quotes_backslashes_and_control_characters() {
        assert_eq!(
            json_string_literal(AWKWARD_TEXT),
            r#""say \"hi\"\\ then\nnext line\ttab é ✓""#
        );
        assert_eq!(json_string_literal("bell \u{7}"), r#""bell \u0007""#);
    }

    #[test]
    fn plain_text_is_only_quoted() {
        assert_eq!(rust_string_literal("RRS-E0001"), "\"RRS-E0001\"");
        assert_eq!(json_string_literal("RRS-E0001"), "\"RRS-E0001\"");
    }
}
